/// The scenes of the fine-tuning groups
#[must_use]
#[rustfmt::skip]
pub fn group_scenes() -> Vec<(&'static str, Vec<SceneName>)> {
    vec![
        ("Feinschliff: Minimes", vec![SceneName::Minimes]),
        ("Feinschliff: Allgemein", vec![SceneName::Starting, SceneName::Brb, SceneName::Ending, SceneName::Alerts, SceneName::Chat, SceneName::Cam, SceneName::Music, SceneName::Stats, SceneName::Fx, SceneName::Minimes, SceneName::Info]),
        ("Feinschliff: Starting, BRB, Ending", vec![SceneName::Starting, SceneName::Brb, SceneName::Ending]),
        ("Feinschliff: Alerts", vec![SceneName::Alerts]),
        ("Feinschliff: Chat", vec![SceneName::Chat]),
        ("Feinschliff: Kamera-Rahmen", vec![SceneName::Cam]),
        ("Feinschliff: Musik", vec![SceneName::Music]),
        ("Feinschliff: Effekte", vec![SceneName::Fx]),
        ("Feinschliff: Befehlsseite", vec![SceneName::Info]),
        ("Feinschliff: Strand", vec![SceneName::Starting, SceneName::Brb, SceneName::Ending, SceneName::Info]),
    ]
}
